        {result.launchStrategy && <div className="bg-gray-800 rounded p-4"><h4 className="text-white font-semibold mb-3">🎯 Launch Strategy</h4><p className="text-gray-300 text-sm mb-2"><span className="text-orange-400 font-medium">Positioning:</span> {result.launchStrategy.positioning}</p><p className="text-gray-300 text-sm mb-2"><span className="text-orange-400 font-medium">UVP:</span> {result.launchStrategy.uniqueValueProp}</p><div className="text-gray-400 text-xs">{result.launchStrategy.targetPersonas?.join(' · ')}</div></div>}
        {result.prelaunchChecklist?.length > 0 && <div className="bg-gray-800 rounded p-4"><h4 className="text-white font-semibold mb-3">✅ Pre-Launch Checklist</h4><div className="space-y-3">{result.prelaunchChecklist.map((cat:any,i:number)=><div key={i}><div className="text-gray-400 text-xs font-semibold uppercase mb-1">{cat.category}</div>{cat.items?.map((item:any,j:number)=><div key={j} className="flex items-center gap-2 py-1"><span className={`text-xs px-2 py-0.5 rounded text-white shrink-0 ${TASK_STATUS_COLOR[item.status]||'bg-gray-600'}`}>{item.status}</span><span className="text-gray-300 text-sm">{item.task}</span></div>)}</div>)}</div></div>}
        {result.channelStrategy?.length > 0 && <div className="bg-gray-800 rounded p-4"><h4 className="text-white font-semibold mb-3">📡 Channel Strategy</h4><div className="space-y-2">{result.channelStrategy.map((c:any,i:number)=><div key={i} className="bg-gray-700 rounded p-3 flex items-start gap-3"><div className="flex-1"><div className="flex items-center gap-2"><span className="text-white text-sm font-medium">{c.channel}</span><span className={`text-xs px-2 py-0.5 rounded text-white ${c.priority==='Primary'?'bg-orange-700':c.priority==='Secondary'?'bg-blue-700':'bg-gray-600'}`}>{c.priority}</span></div><div className="text-gray-400 text-xs mt-1">{c.tactics?.[0]} · {c.expectedReach}</div></div><div className="text-green-400 text-sm font-medium shrink-0">{c.budget}</div></div>)}</div></div>}
