  const [form, setForm] = useState({ company:'', industry:'', companySize:'', currentTechStack:'', digitalMaturity:'', budget:'', timeHorizon:'', businessGoals:'', painPoints:'', competitors:'', customerExperience:'', operationalChallenges:'', dataCapabilities:'', securityPosture:'', changeReadiness:'', leadership:'', transformationGoals:'' });
