  const run = async () => { setLoading(true); setError(''); try { const r = await fetch(`${api}/api/board-prep`, { method:'POST', headers:{'Content-Type':'application/json',...( (window as any).__forgeAuth ? {Authorization:`Bearer ${(window as any).__forgeAuth}`} : {})}, body: JSON.stringify(form) }); const d = await r.json(); if (!d.success) throw new Error(d.error); setResult(d); } catch(e:any){setError(e.message);} finally{setLoading(false);}};
  const SECTIONS = [['agenda','📋 Agenda'],['decisions','✅ Decisions'],['questions','❓ Q&A Prep'],['financial','💰 Financial'],['strategic','🎯 Strategic']];
